WITH oracle_1 AS (WITH w AS (SELECT mktcode,tgtcode,bizdate,lowPx/10000.0 AS px,MIN(lowPx/10000.0) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS extreme FROM `newzl`.`hsj_stock_hq_basic`) SELECT mktcode,tgtcode,bizdate FROM w WHERE bizdate='2026-04-14' AND px<=extreme), branch_1 AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM oracle_1 o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE q.mktcode=0 AND q.volume>=0), oracle_2 AS (WITH w AS (SELECT b.mktcode,b.tgtcode,b.bizdate,b.lastPx/10000.0 AS px,t.ma30,LAG(b.lastPx/10000.0) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate) AS ppx,LAG(t.ma30) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate) AS pma FROM `newzl`.`hsj_stock_hq_basic` AS b LEFT JOIN `newzl`.`hsj_stock_hq_basic_technical` AS t ON t.mktcode=b.mktcode AND t.tgtcode=b.tgtcode AND t.bizdate=b.bizdate) SELECT mktcode,tgtcode,bizdate FROM w WHERE bizdate='2026-04-14' AND px<ma30 AND ppx>=pma), branch_2 AS (SELECT o.mktcode,o.tgtcode,o.bizdate FROM oracle_2 o INNER JOIN newzl.hsj_stock_hq_basic q ON q.mktcode=o.mktcode AND q.tgtcode=o.tgtcode AND q.bizdate=o.bizdate WHERE 1=1 AND q.volume>=0) SELECT l.mktcode,l.tgtcode,l.bizdate FROM branch_1 l INNER JOIN branch_2 r ON r.mktcode=l.mktcode AND r.tgtcode=l.tgtcode AND r.bizdate=l.bizdate;
